import React, { createContext, useContext, useReducer, useCallback, useEffect } from 'react';
import type { FilterState, Project } from '../types';
import { filterProjects, createShareableURL, getFilterStats } from '../utils/filters';

interface FilterContextState {
  filters: FilterState;
  filteredProjects: Project[];
  isFiltering: boolean;
  hasActiveFilters: boolean;
  filterStats: {
    total: number;
    filtered: number;
    percentage: number;
    hasFilters: boolean;
  };
  updateFilters: (newFilters: FilterState) => void;
  clearAllFilters: () => void;
  clearSearchQuery: () => void;
  setProjects: (projects: Project[]) => void;
  getShareableURL: () => string;
}

interface FilterContextProviderProps {
  children: React.ReactNode;
  initialFilters?: Partial<FilterState>;
}

const defaultFilters: FilterState = {
  searchQuery: '',
  technologies: [],
  categories: [],
  status: [],
};

type FilterAction =
  | { type: 'UPDATE_FILTERS'; payload: FilterState }
  | { type: 'CLEAR_ALL_FILTERS' }
  | { type: 'CLEAR_SEARCH_QUERY' }
  | { type: 'SET_PROJECTS'; payload: Project[] }
  | { type: 'SET_FILTERED_PROJECTS'; payload: Project[] }
  | { type: 'SET_IS_FILTERING'; payload: boolean };

interface FilterReducerState {
  filters: FilterState;
  allProjects: Project[];
  filteredProjects: Project[];
  isFiltering: boolean;
}

const filterReducer = (state: FilterReducerState, action: FilterAction): FilterReducerState => {
  switch (action.type) {
    case 'UPDATE_FILTERS':
      return {
        ...state,
        filters: action.payload,
        isFiltering: true,
      };

    case 'CLEAR_ALL_FILTERS':
      return {
        ...state,
        filters: defaultFilters,
        filteredProjects: state.allProjects,
        isFiltering: false,
      };

    case 'CLEAR_SEARCH_QUERY':
      return {
        ...state,
        filters: {
          ...state.filters,
          searchQuery: '',
        },
      };

    case 'SET_PROJECTS':
      return {
        ...state,
        allProjects: action.payload,
        filteredProjects: action.payload,
      };

    case 'SET_FILTERED_PROJECTS':
      return {
        ...state,
        filteredProjects: action.payload,
        isFiltering: false,
      };

    case 'SET_IS_FILTERING':
      return {
        ...state,
        isFiltering: action.payload,
      };

    default:
      return state;
  }
};

const FilterContext = createContext<FilterContextState | undefined>(undefined);

export const FilterProvider: React.FC<FilterContextProviderProps> = ({
  children,
  initialFilters = {},
}) => {
  const [state, dispatch] = useReducer(filterReducer, {
    filters: { ...defaultFilters, ...initialFilters },
    allProjects: [],
    filteredProjects: [],
    isFiltering: false,
  });

  // Apply filters whenever filters or projects change
  useEffect(() => {
    if (state.allProjects.length === 0) return;

    dispatch({ type: 'SET_IS_FILTERING', payload: true });

    // Debounce filtering for search queries
    const timeoutId = setTimeout(() => {
      const filtered = filterProjects(state.allProjects, state.filters);
      dispatch({ type: 'SET_FILTERED_PROJECTS', payload: filtered });
    }, state.filters.searchQuery ? 300 : 0);

    return () => clearTimeout(timeoutId);
  }, [state.filters, state.allProjects]);

  // Sync filters with URL parameters
  useEffect(() => {
    const updateURL = () => {
      const url = new URL(window.location.href);
      const params = new URLSearchParams();

      // Add search query
      if (state.filters.searchQuery) {
        params.set('search', state.filters.searchQuery);
      }

      // Add technologies
      if (state.filters.technologies.length > 0) {
        params.set('technologies', state.filters.technologies.join(','));
      }

      // Add categories
      if (state.filters.categories.length > 0) {
        params.set('categories', state.filters.categories.join(','));
      }

      // Add status
      if (state.filters.status.length > 0) {
        params.set('status', state.filters.status.join(','));
      }

      // Update URL without triggering navigation
      const newUrl = params.toString() 
        ? `${url.pathname}?${params.toString()}`
        : url.pathname;
      
      window.history.replaceState({}, '', newUrl);
    };

    updateURL();
  }, [state.filters]);

  const updateFilters = useCallback((newFilters: FilterState) => {
    dispatch({ type: 'UPDATE_FILTERS', payload: newFilters });
  }, []);

  const clearAllFilters = useCallback(() => {
    dispatch({ type: 'CLEAR_ALL_FILTERS' });
  }, []);

  const clearSearchQuery = useCallback(() => {
    dispatch({ type: 'CLEAR_SEARCH_QUERY' });
  }, []);

  const setProjects = useCallback((projects: Project[]) => {
    dispatch({ type: 'SET_PROJECTS', payload: projects });
  }, []);

  // Check if any filters are active
  const hasActiveFilters = 
    state.filters.searchQuery.length > 0 ||
    state.filters.technologies.length > 0 ||
    state.filters.categories.length > 0 ||
    state.filters.status.length > 0;

  // Get filter statistics
  const filterStats = getFilterStats(state.allProjects, state.filteredProjects, state.filters);

  // Get shareable URL function
  const getShareableURL = useCallback(() => {
    return createShareableURL(state.filters);
  }, [state.filters]);

  const contextValue: FilterContextState = {
    filters: state.filters,
    filteredProjects: state.filteredProjects,
    isFiltering: state.isFiltering,
    hasActiveFilters,
    filterStats,
    updateFilters,
    clearAllFilters,
    clearSearchQuery,
    setProjects,
    getShareableURL,
  };

  return (
    <FilterContext.Provider value={contextValue}>
      {children}
    </FilterContext.Provider>
  );
};

export const useFilters = (): FilterContextState => {
  const context = useContext(FilterContext);
  if (context === undefined) {
    throw new Error('useFilters must be used within a FilterProvider');
  }
  return context;
};

// Hook to initialize filters from URL parameters
export const useInitialFiltersFromURL = (): Partial<FilterState> => {
  const getFiltersFromURL = useCallback((): Partial<FilterState> => {
    const params = new URLSearchParams(window.location.search);
    const filters: Partial<FilterState> = {};

    const search = params.get('search');
    if (search) {
      filters.searchQuery = search;
    }

    const technologies = params.get('technologies');
    if (technologies) {
      filters.technologies = technologies.split(',').filter(Boolean);
    }

    const categories = params.get('categories');
    if (categories) {
      filters.categories = categories.split(',').filter(Boolean);
    }

    const status = params.get('status');
    if (status) {
      filters.status = status.split(',').filter(Boolean);
    }

    return filters;
  }, []);

  return getFiltersFromURL();
};