/**
 * Performance monitoring and Core Web Vitals tracking
 */

export interface PerformanceMetrics {
  fcp?: number; // First Contentful Paint
  lcp?: number; // Largest Contentful Paint
  fid?: number; // First Input Delay
  cls?: number; // Cumulative Layout Shift
  ttfb?: number; // Time to First Byte
  tti?: number; // Time to Interactive
}

export interface NavigationMetrics {
  domContentLoaded: number;
  loadComplete: number;
  firstPaint: number;
  firstContentfulPaint: number;
}

export interface ResourceMetrics {
  name: string;
  type: string;
  size: number;
  duration: number;
  startTime: number;
}

class PerformanceMonitor {
  private metrics: PerformanceMetrics = {};
  private observers: PerformanceObserver[] = [];
  private analyticsCallback?: (metrics: PerformanceMetrics) => void;

  constructor() {
    this.initializeObservers();
  }

  /**
   * Set callback for analytics reporting
   */
  setAnalyticsCallback(callback: (metrics: PerformanceMetrics) => void) {
    this.analyticsCallback = callback;
  }

  /**
   * Initialize performance observers
   */
  private initializeObservers() {
    // First Contentful Paint
    this.observePaintMetrics();
    
    // Largest Contentful Paint
    this.observeLCP();
    
    // First Input Delay
    this.observeFID();
    
    // Cumulative Layout Shift
    this.observeCLS();
    
    // Time to First Byte
    this.measureTTFB();
  }

  /**
   * Observe paint metrics (FCP)
   */
  private observePaintMetrics() {
    if (!('PerformanceObserver' in window)) return;

    try {
      const observer = new PerformanceObserver((list) => {
        const entries = list.getEntries();
        entries.forEach((entry) => {
          if (entry.name === 'first-contentful-paint') {
            this.metrics.fcp = entry.startTime;
            this.reportMetric('FCP', entry.startTime);
          }
        });
      });

      observer.observe({ entryTypes: ['paint'] });
      this.observers.push(observer);
    } catch (error) {
      console.warn('Failed to observe paint metrics:', error);
    }
  }

  /**
   * Observe Largest Contentful Paint
   */
  private observeLCP() {
    if (!('PerformanceObserver' in window)) return;

    try {
      const observer = new PerformanceObserver((list) => {
        const entries = list.getEntries();
        const lastEntry = entries[entries.length - 1];
        if (lastEntry) {
          this.metrics.lcp = lastEntry.startTime;
          this.reportMetric('LCP', lastEntry.startTime);
        }
      });

      observer.observe({ entryTypes: ['largest-contentful-paint'] });
      this.observers.push(observer);
    } catch (error) {
      console.warn('Failed to observe LCP:', error);
    }
  }

  /**
   * Observe First Input Delay
   */
  private observeFID() {
    if (!('PerformanceObserver' in window)) return;

    try {
      const observer = new PerformanceObserver((list) => {
        const entries = list.getEntries();
        entries.forEach((entry: any) => {
          if (entry.name === 'first-input') {
            const fid = entry.processingStart - entry.startTime;
            this.metrics.fid = fid;
            this.reportMetric('FID', fid);
          }
        });
      });

      observer.observe({ entryTypes: ['first-input'] });
      this.observers.push(observer);
    } catch (error) {
      console.warn('Failed to observe FID:', error);
    }
  }

  /**
   * Observe Cumulative Layout Shift
   */
  private observeCLS() {
    if (!('PerformanceObserver' in window)) return;

    try {
      let clsValue = 0;
      const observer = new PerformanceObserver((list) => {
        const entries = list.getEntries();
        entries.forEach((entry: any) => {
          if (!entry.hadRecentInput) {
            clsValue += entry.value;
          }
        });
        this.metrics.cls = clsValue;
        this.reportMetric('CLS', clsValue);
      });

      observer.observe({ entryTypes: ['layout-shift'] });
      this.observers.push(observer);
    } catch (error) {
      console.warn('Failed to observe CLS:', error);
    }
  }

  /**
   * Measure Time to First Byte
   */
  private measureTTFB() {
    try {
      const navigationEntry = performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming;
      if (navigationEntry) {
        const ttfb = navigationEntry.responseStart - navigationEntry.requestStart;
        this.metrics.ttfb = ttfb;
        this.reportMetric('TTFB', ttfb);
      }
    } catch (error) {
      console.warn('Failed to measure TTFB:', error);
    }
  }

  /**
   * Get navigation timing metrics
   */
  getNavigationMetrics(): NavigationMetrics | null {
    try {
      const navigationEntry = performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming;
      if (!navigationEntry) return null;

      return {
        domContentLoaded: navigationEntry.domContentLoadedEventEnd - ('navigationStart' in navigationEntry ? (navigationEntry as any).navigationStart : 0),
        loadComplete: navigationEntry.loadEventEnd - ('navigationStart' in navigationEntry ? (navigationEntry as any).navigationStart : 0),
        firstPaint: this.metrics.fcp || 0,
        firstContentfulPaint: this.metrics.fcp || 0
      };
    } catch (error) {
      console.warn('Failed to get navigation metrics:', error);
      return null;
    }
  }

  /**
   * Get resource loading metrics
   */
  getResourceMetrics(): ResourceMetrics[] {
    try {
      const resourceEntries = performance.getEntriesByType('resource') as PerformanceResourceTiming[];
      
      return resourceEntries.map(entry => ({
        name: entry.name,
        type: this.getResourceType(entry.name),
        size: entry.transferSize || 0,
        duration: entry.responseEnd - entry.requestStart,
        startTime: entry.startTime
      }));
    } catch (error) {
      console.warn('Failed to get resource metrics:', error);
      return [];
    }
  }

  /**
   * Get resource type from URL
   */
  private getResourceType(url: string): string {
    if (url.match(/\.(js|mjs)$/)) return 'script';
    if (url.match(/\.css$/)) return 'stylesheet';
    if (url.match(/\.(jpg|jpeg|png|gif|webp|avif|svg)$/)) return 'image';
    if (url.match(/\.(woff|woff2|ttf|eot)$/)) return 'font';
    if (url.match(/\.(json|xml)$/)) return 'data';
    return 'other';
  }

  /**
   * Report metric to analytics
   */
  private reportMetric(name: string, value: number) {
    console.log(`Performance Metric - ${name}: ${Math.round(value)}ms`);
    
    if (this.analyticsCallback) {
      this.analyticsCallback({ [name.toLowerCase()]: value });
    }

    // Report to Google Analytics if available
    if (typeof (window as any).gtag !== "undefined") {
      (window as any).gtag('event', name, {
        event_category: 'Web Vitals',
        value: Math.round(value),
        non_interaction: true,
      });
    }
  }

  /**
   * Get all collected metrics
   */
  getMetrics(): PerformanceMetrics {
    return { ...this.metrics };
  }

  /**
   * Get performance score based on Core Web Vitals
   */
  getPerformanceScore(): { score: number; details: any } {
    const { fcp, lcp, fid, cls } = this.metrics;
    
    let score = 0;
    const details: any = {};

    // FCP scoring (0-40 points)
    if (fcp !== undefined) {
      if (fcp <= 1800) {
        details.fcp = { score: 40, rating: 'good' };
        score += 40;
      } else if (fcp <= 3000) {
        details.fcp = { score: 20, rating: 'needs-improvement' };
        score += 20;
      } else {
        details.fcp = { score: 0, rating: 'poor' };
      }
    }

    // LCP scoring (0-25 points)
    if (lcp !== undefined) {
      if (lcp <= 2500) {
        details.lcp = { score: 25, rating: 'good' };
        score += 25;
      } else if (lcp <= 4000) {
        details.lcp = { score: 12, rating: 'needs-improvement' };
        score += 12;
      } else {
        details.lcp = { score: 0, rating: 'poor' };
      }
    }

    // FID scoring (0-25 points)
    if (fid !== undefined) {
      if (fid <= 100) {
        details.fid = { score: 25, rating: 'good' };
        score += 25;
      } else if (fid <= 300) {
        details.fid = { score: 12, rating: 'needs-improvement' };
        score += 12;
      } else {
        details.fid = { score: 0, rating: 'poor' };
      }
    }

    // CLS scoring (0-10 points)
    if (cls !== undefined) {
      if (cls <= 0.1) {
        details.cls = { score: 10, rating: 'good' };
        score += 10;
      } else if (cls <= 0.25) {
        details.cls = { score: 5, rating: 'needs-improvement' };
        score += 5;
      } else {
        details.cls = { score: 0, rating: 'poor' };
      }
    }

    return { score, details };
  }

  /**
   * Generate performance report
   */
  generateReport(): string {
    const metrics = this.getMetrics();
    const navigationMetrics = this.getNavigationMetrics();
    const resourceMetrics = this.getResourceMetrics();
    const performanceScore = this.getPerformanceScore();

    const report = `
Performance Report
==================

Core Web Vitals:
- First Contentful Paint: ${metrics.fcp ? Math.round(metrics.fcp) + 'ms' : 'N/A'}
- Largest Contentful Paint: ${metrics.lcp ? Math.round(metrics.lcp) + 'ms' : 'N/A'}
- First Input Delay: ${metrics.fid ? Math.round(metrics.fid) + 'ms' : 'N/A'}
- Cumulative Layout Shift: ${metrics.cls ? metrics.cls.toFixed(3) : 'N/A'}
- Time to First Byte: ${metrics.ttfb ? Math.round(metrics.ttfb) + 'ms' : 'N/A'}

Performance Score: ${performanceScore.score}/100

Navigation Timing:
${navigationMetrics ? `
- DOM Content Loaded: ${Math.round(navigationMetrics.domContentLoaded)}ms
- Load Complete: ${Math.round(navigationMetrics.loadComplete)}ms
` : 'N/A'}

Resource Summary:
- Total Resources: ${resourceMetrics.length}
- Scripts: ${resourceMetrics.filter(r => r.type === 'script').length}
- Stylesheets: ${resourceMetrics.filter(r => r.type === 'stylesheet').length}
- Images: ${resourceMetrics.filter(r => r.type === 'image').length}
- Fonts: ${resourceMetrics.filter(r => r.type === 'font').length}
`;

    return report;
  }

  /**
   * Clean up observers
   */
  disconnect() {
    this.observers.forEach(observer => observer.disconnect());
    this.observers = [];
  }
}

// Global performance monitor instance
export const performanceMonitor = new PerformanceMonitor();

/**
 * Initialize performance monitoring with analytics integration
 */
export function initializePerformanceMonitoring(analyticsId?: string) {
  // Set up analytics callback
  performanceMonitor.setAnalyticsCallback((metrics) => {
    console.log('Performance metrics collected:', metrics);
  });

  // Report metrics after page load
  window.addEventListener('load', () => {
    setTimeout(() => {
      const report = performanceMonitor.generateReport();
      console.log(report);
    }, 5000);
  });

  // Report metrics before page unload
  window.addEventListener('beforeunload', () => {
    const metrics = performanceMonitor.getMetrics();
    
    // Use sendBeacon for reliable metric reporting
    if (navigator.sendBeacon && analyticsId) {
      const data = JSON.stringify({
        metrics,
        timestamp: Date.now(),
        url: window.location.href
      });
      
      navigator.sendBeacon('/api/analytics/performance', data);
    }
  });
}

/**
 * Measure custom performance marks
 */
export function measureCustomMetric(name: string, startMark?: string, endMark?: string) {
  try {
    if (startMark && endMark) {
      performance.measure(name, startMark, endMark);
    } else {
      performance.mark(name);
    }
    
    const entries = performance.getEntriesByName(name);
    const latestEntry = entries[entries.length - 1];
    
    if (latestEntry) {
      console.log(`Custom Metric - ${name}: ${Math.round(latestEntry.duration || latestEntry.startTime)}ms`);
    }
    
    return latestEntry;
  } catch (error) {
    console.warn(`Failed to measure custom metric ${name}:`, error);
    return null;
  }
}

/**
 * Monitor long tasks that block the main thread
 */
export function monitorLongTasks() {
  if (!('PerformanceObserver' in window)) return;

  try {
    const observer = new PerformanceObserver((list) => {
      const entries = list.getEntries();
      entries.forEach((entry) => {
        console.warn(`Long Task detected: ${Math.round(entry.duration)}ms`, entry);
        
        // Report to analytics
        if (typeof (window as any).gtag !== "undefined") {
          (window as any).gtag('event', 'long_task', {
            event_category: 'Performance',
            value: Math.round(entry.duration),
            non_interaction: true,
          });
        }
      });
    });

    observer.observe({ entryTypes: ['longtask'] });
  } catch (error) {
    console.warn('Failed to monitor long tasks:', error);
  }
}