import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App.tsx';
import { registerSW, reportWebVitals, promptForUpdate } from './utils/serviceWorker';
import { initializePerformanceMonitoring, monitorLongTasks } from './utils/performanceMonitoring';
import { preloadCriticalImages } from './utils/imageOptimization';
import './index.css';

// Initialize performance monitoring
initializePerformanceMonitoring(import.meta.env.VITE_ANALYTICS_ID || "");
monitorLongTasks();

// Preload critical images
const criticalImages = [
  { src: `${import.meta.env.BASE_URL}hero-image.jpg`, priority: 'high' as const },
  { src: `${import.meta.env.BASE_URL}logo.png`, priority: 'high' as const }
];
preloadCriticalImages(criticalImages);

// Register service worker for caching and offline support
registerSW({
  onSuccess: () => {
    console.log('SW registered successfully');
  },
  onUpdate: (registration) => {
    console.log('SW updated, prompting user');
    promptForUpdate(registration);
  },
  onOfflineReady: () => {
    console.log('App ready for offline use');
  }
});

// Report Core Web Vitals for performance monitoring
reportWebVitals().then((metrics) => {
  console.log('Performance metrics collected:', metrics);
});

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error('Root element not found');
}

ReactDOM.createRoot(rootElement).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

// Hide the initial HTML loading spinner as soon as React has mounted
const hideSpinner = (window as unknown as { __hideInitialSpinner?: () => void }).__hideInitialSpinner;
if (typeof hideSpinner === 'function') hideSpinner();