import React, { useState, useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { createFocusTrap, announceToScreenReader, createRovingTabIndex } from '../utils/focusManagement';
import SearchInput from './SearchInput';
import './Header.css';

interface HeaderProps {
  searchValue?: string;
  onSearchChange?: (value: string) => void;
  searchSuggestions?: string[];
  onSuggestionSelect?: (suggestion: string) => void;
}

const Header: React.FC<HeaderProps> = ({ 
  searchValue = '', 
  onSearchChange, 
  searchSuggestions = [], 
  onSuggestionSelect 
}) => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const location = useLocation();
  const mobileMenuRef = useRef<HTMLElement>(null);
  const focusTrapRef = useRef<any>(null);
  const rovingTabIndexRef = useRef<any>(null);
  const toggleButtonRef = useRef<HTMLButtonElement>(null);

  const closeMobileMenu = () => {
    setIsMobileMenuOpen(false);
    announceToScreenReader('Mobile menu closed', 'assertive');
    
    // Return focus to toggle button when closing menu
    if (toggleButtonRef.current) {
      toggleButtonRef.current.focus();
    }
  };

  // Handle keyboard navigation in mobile menu
  const handleMobileMenuKeyDown = (event: KeyboardEvent) => {
    if (!isMobileMenuOpen) return;

    switch (event.key) {
      case 'Escape':
        event.preventDefault();
        closeMobileMenu();
        break;
      case 'Tab':
        // Focus trap is handled by the focus trap utility
        break;
    }
  };

  // Set up focus management for mobile menu
  useEffect(() => {
    if (isMobileMenuOpen && mobileMenuRef.current) {
      // Create focus trap for mobile menu
      focusTrapRef.current = createFocusTrap(mobileMenuRef.current);
      focusTrapRef.current.activate();

      // Set up keyboard navigation
      document.addEventListener('keydown', handleMobileMenuKeyDown);
      
      // Set up roving tab index for menu items
      setTimeout(() => {
        if (mobileMenuRef.current) {
          rovingTabIndexRef.current = createRovingTabIndex(
            mobileMenuRef.current,
            '.nav-link--mobile'
          );
        }
      }, 100);

      // Prevent body scroll when menu is open
      document.body.style.overflow = 'hidden';
    } else {
      // Clean up focus trap
      if (focusTrapRef.current) {
        focusTrapRef.current.deactivate();
        focusTrapRef.current = null;
      }

      // Clean up roving tab index
      if (rovingTabIndexRef.current) {
        rovingTabIndexRef.current.destroy();
        rovingTabIndexRef.current = null;
      }

      document.removeEventListener('keydown', handleMobileMenuKeyDown);
      document.body.style.overflow = 'unset';
    }

    return () => {
      if (focusTrapRef.current) {
        focusTrapRef.current.deactivate();
      }
      if (rovingTabIndexRef.current) {
        rovingTabIndexRef.current.destroy();
      }
      document.removeEventListener('keydown', handleMobileMenuKeyDown);
      document.body.style.overflow = 'unset';
    };
  }, [isMobileMenuOpen]);

  // Close menu on route change
  useEffect(() => {
    if (isMobileMenuOpen) {
      closeMobileMenu();
    }
  }, [location.pathname]);

  // Close menu on window resize to desktop size
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth > 768 && isMobileMenuOpen) {
        closeMobileMenu();
      }
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [isMobileMenuOpen]);

  return (
    <header className="header" role="banner">
      <div className="header-container">
        <div className="logo">
          <h1>Portfolio <span className="logo__name">Craig Ng</span></h1>
        </div>
        
        {/* Search Bar on Top Right */}
        <div className="header__search">
          {onSearchChange && (
            <SearchInput
              value={searchValue}
              onChange={onSearchChange}
              suggestions={searchSuggestions}
              onSuggestionSelect={onSuggestionSelect || (() => {})}
              placeholder="Search projects..."
            />
          )}
        </div>
      </div>
    </header>
  );
};

export default Header;