import React from 'react';
import { useOnlineStatus } from '../hooks/useOnlineStatus';
import './OfflineMessage.css';

interface OfflineMessageProps {
  className?: string;
  onRetry?: () => void;
}

const OfflineMessage: React.FC<OfflineMessageProps> = ({
  className = '',
  onRetry
}) => {
  const { isOffline } = useOnlineStatus();

  if (!isOffline) {
    return null;
  }

  return (
    <div 
      className={`offline-message ${className}`}
      role="alert"
      aria-live="assertive"
    >
      <div className="offline-message__content">
        <div className="offline-message__icon">
          <svg
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <path d="M16.5 9.4 7 19l-3-3m5.5-7L16.5 2l3 3-8.5 8.5" />
            <path d="M7.5 4.3 19 16l-3 3L4.5 7.3l3-3" />
          </svg>
        </div>
        <div className="offline-message__text">
          <span className="offline-message__title">You're offline</span>
          <span className="offline-message__description">
            Check your internet connection and try again.
          </span>
        </div>
        {onRetry && (
          <button
            className="offline-message__retry"
            onClick={onRetry}
            type="button"
            aria-label="Retry when back online"
          >
            <svg
              width="16"
              height="16"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <polyline points="23 4 23 10 17 10" />
              <polyline points="1 20 1 14 7 14" />
              <path d="M20.49 9A9 9 0 0 0 5.64 5.64L1 10m22 4-4.64 4.36A9 9 0 0 1 3.51 15" />
            </svg>
          </button>
        )}
      </div>
    </div>
  );
};

export default OfflineMessage;